solutions.naive:
class Solution:
    def integerBreak(self, n: int) -> int:
        def best(x: int) -> int:
            ans = 0
            for first in range(1, x):
                ans = max(ans, first * (x - first), first * best(x - first))
            return ans
        return best(n)

