class Solution:
    def integerBreak(self, n: int) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def best(x: int) -> int:
            ans = 0
            for first in range(1, x):
                ans = max(ans, first * (x - first), first * best(x - first))
            return ans
        return best(n)

solutions.optimal:
class Solution:
    def integerBreak(self, n: int) -> int:
        if n <= 3:
            return n - 1
        product = 1
        while n > 4:
            product *= 3
            n -= 3
        return product * n

